//! The TypeScript text of `web/src/gen/api.ts`, a pure function of the
//! registry. Every name and path in the registry is ASCII, and every
//! string goes through [`ts_str`], so no registry text can end a literal.

use fstp_access::{Classification, Method, OpSpec, Scope, SessionNeed, route_params};

/// The header of the generated file.
const HEADER: &str = "\
// Operation types, the operation table, route segments and structural
// validators, generated from the OPS registry of fstp-access by
// tools/gen-ts (M4 design sections 1.1 and 3.9, ADR-014).
//
// Do not edit this file. Regenerate it with
//   cargo run -p gen-ts -- --root .
// CI checks it with
//   cargo run -p gen-ts -- --check --root .
//
// Paths are relative to API_PREFIX, except the public pages (base \"page\"),
// which are served at their own path with no script.
";

/// The fixed part after the operation table: lookups and the structural
/// validators for the JSON bodies the API core returns (design section
/// 3.7). Each validator refuses members it does not know, as the server's
/// decoders do.
const TAIL: &str = r#"
/** The operation named `name`. */
export function operation(name: OpName): Operation {
  for (const op of OPERATIONS) {
    if (op.name === name) {
      return op;
    }
  }
  throw new Error("unknown operation");
}

/** Whether `v` names an operation of the registry. */
export function isOpName(v: unknown): v is OpName {
  return typeof v === "string" && (OP_NAMES as readonly string[]).includes(v);
}

/** Whether `v` is an object parsed from JSON, not null and not an array. */
function isRecord(v: unknown): v is Readonly<Record<string, unknown>> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** Whether every member of `v` is one of `allowed`. */
function onlyMembers(v: Readonly<Record<string, unknown>>, allowed: readonly string[]): boolean {
  for (const k of Object.keys(v)) {
    if (!allowed.includes(k)) {
      return false;
    }
  }
  return true;
}

/** A refusal: a stable code and the rule text only, never an account. */
export interface ApiErrorBody {
  readonly code: string;
  readonly rule?: string;
}

/** Whether `v` is an `ApiErrorBody`, with no other member. */
export function isApiErrorBody(v: unknown): v is ApiErrorBody {
  if (!isRecord(v) || !onlyMembers(v, ["code", "rule"])) {
    return false;
  }
  if (typeof v["code"] !== "string") {
    return false;
  }
  return !("rule" in v) || typeof v["rule"] === "string";
}

/** A call that became a pending action for a confirmation in the platform (I-85). */
export interface PendingReceipt {
  readonly status: "awaiting_confirmation";
  readonly confirm_path: string;
  readonly expires: string;
}

/** Whether `v` is a `PendingReceipt`, with no other member. */
export function isPendingReceipt(v: unknown): v is PendingReceipt {
  if (!isRecord(v) || !onlyMembers(v, ["status", "confirm_path", "expires"])) {
    return false;
  }
  return (
    v["status"] === "awaiting_confirmation" &&
    typeof v["confirm_path"] === "string" &&
    typeof v["expires"] === "string"
  );
}
"#;

/// A TypeScript string literal of `s`, in double quotes.
pub(crate) fn ts_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len().saturating_add(2));
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if c.is_ascii_graphic() || c == ' ' => out.push(c),
            c => out.push_str(&format!("\\u{{{:x}}}", u32::from(c))),
        }
    }
    out.push('"');
    out
}

fn method(m: Method) -> &'static str {
    m.as_str()
}

fn classification(c: Classification) -> &'static str {
    c.as_str()
}

fn session(s: SessionNeed) -> &'static str {
    s.as_str()
}

/// A union type of string literals, one per line.
fn union(name: &str, doc: &str, members: &[String]) -> String {
    let mut out = format!("/** {doc} */\nexport type {name} =\n");
    for (i, m) in members.iter().enumerate() {
        let end = if i.saturating_add(1) == members.len() {
            ";"
        } else {
            ""
        };
        out.push_str(&format!("  | {m}{end}\n"));
    }
    if members.is_empty() {
        out.push_str("  never;\n");
    }
    out.push('\n');
    out
}

/// The route segments of `path`, as a TypeScript array literal.
fn segments(path: &str) -> String {
    let parts: Vec<String> = path
        .split('/')
        .filter(|s| !s.is_empty())
        .map(
            |s| match s.strip_prefix('{').and_then(|s| s.strip_suffix('}')) {
                Some(name) => format!("{{ kind: \"param\", name: {} }}", ts_str(name)),
                None => format!("{{ kind: \"literal\", text: {} }}", ts_str(s)),
            },
        )
        .collect();
    format!("[{}]", parts.join(", "))
}

/// The path parameters of `path`, as a TypeScript array literal.
fn params(path: &str) -> String {
    let names: Vec<String> = route_params(path).map(ts_str).collect();
    format!("[{}]", names.join(", "))
}

/// One entry of the operation table.
fn entry(op: &OpSpec) -> String {
    let (m, path) = op.route.unwrap_or((Method::Get, ""));
    let base = if path.starts_with("/p/") || path == "/p" {
        "page"
    } else {
        "api"
    };
    let tool = match op.tool {
        Some(t) => format!(
            "{{ name: {}, scope: {}, prepareOnly: {} }}",
            ts_str(t.name),
            match op.scope {
                Some(s) => ts_str(s.as_str()),
                None => "null".to_string(),
            },
            t.prepare_only
        ),
        None => "null".to_string(),
    };
    let body = !matches!(m, Method::Get);
    format!(
        "  {{\n    name: {},\n    method: {},\n    path: {},\n    base: {},\n    segments: {},\n    params: {},\n    body: {},\n    highRisk: {},\n    binding: {},\n    session: {},\n    classification: {},\n    tool: {},\n  }},\n",
        ts_str(op.name),
        ts_str(method(m)),
        ts_str(path),
        ts_str(base),
        segments(path),
        params(path),
        body,
        op.high_risk,
        op.binding,
        ts_str(session(op.session)),
        ts_str(classification(op.classification)),
        tool,
    )
}

/// The parameter record type of one operation.
fn param_type(op: &OpSpec) -> String {
    let path = op.route.map_or("", |(_, p)| p);
    let names: Vec<String> = route_params(path)
        .map(|n| format!("readonly {}: string", ts_str(n)))
        .collect();
    if names.is_empty() {
        "Readonly<Record<never, string>>".to_string()
    } else {
        format!("{{ {} }}", names.join("; "))
    }
}

/// The whole file for `ops`.
pub(crate) fn render(ops: &[OpSpec]) -> String {
    let mut out = String::from(HEADER);
    out.push('\n');
    out.push_str("/** The prefix of every API route. */\n");
    out.push_str("export const API_PREFIX = \"/api/v1\";\n\n");
    out.push_str("/** An HTTP method of a web route. */\n");
    out.push_str("export type Method = \"GET\" | \"POST\" | \"PUT\" | \"DELETE\";\n\n");
    out.push_str("/** Where a route is served: under API_PREFIX, or as a public page. */\n");
    out.push_str("export type Base = \"api\" | \"page\";\n\n");
    out.push_str(&union(
        "Classification",
        "How an MCP response classifies its data.",
        &[
            Classification::Public,
            Classification::Confidential,
            Classification::Personal,
        ]
        .iter()
        .map(|c| ts_str(c.as_str()))
        .collect::<Vec<_>>(),
    ));
    out.push_str(&union(
        "SessionNeed",
        "The session strength an operation needs (I-77).",
        &[SessionNeed::Any, SessionNeed::PhishingResistant]
            .iter()
            .map(|s| ts_str(s.as_str()))
            .collect::<Vec<_>>(),
    ));
    out.push_str(&union(
        "Scope",
        "An OAuth scope issued in M4.",
        &Scope::ALL
            .iter()
            .map(|s| ts_str(s.as_str()))
            .collect::<Vec<_>>(),
    ));
    out.push_str(&union(
        "OpName",
        "The name of an operation of the registry.",
        &ops.iter().map(|o| ts_str(o.name)).collect::<Vec<_>>(),
    ));
    out.push_str(
        "/** One segment of a route: fixed text, or a named parameter. */\n\
         export type Segment =\n\
         \x20 | { readonly kind: \"literal\"; readonly text: string }\n\
         \x20 | { readonly kind: \"param\"; readonly name: string };\n\n",
    );
    out.push_str(
        "/** The MCP tool of an operation. Public tools need no scope. */\n\
         export interface Tool {\n\
         \x20 readonly name: string;\n\
         \x20 readonly scope: Scope | null;\n\
         \x20 readonly prepareOnly: boolean;\n\
         }\n\n",
    );
    out.push_str(
        "/** One operation of the registry, as the application sees it. */\n\
         export interface Operation {\n\
         \x20 readonly name: OpName;\n\
         \x20 readonly method: Method;\n\
         \x20 readonly path: string;\n\
         \x20 readonly base: Base;\n\
         \x20 readonly segments: readonly Segment[];\n\
         \x20 readonly params: readonly string[];\n\
         \x20 readonly body: boolean;\n\
         \x20 readonly highRisk: boolean;\n\
         \x20 readonly binding: boolean;\n\
         \x20 readonly session: SessionNeed;\n\
         \x20 readonly classification: Classification;\n\
         \x20 readonly tool: Tool | null;\n\
         }\n\n",
    );
    out.push_str("/** The path parameters of each operation, by name. */\n");
    out.push_str("export interface OpParams {\n");
    for op in ops {
        out.push_str(&format!(
            "  readonly {}: {};\n",
            ts_str(op.name),
            param_type(op)
        ));
    }
    out.push_str("}\n\n");
    out.push_str("/** Every operation name, in registry order. */\n");
    out.push_str("export const OP_NAMES: readonly OpName[] = [\n");
    for op in ops {
        out.push_str(&format!("  {},\n", ts_str(op.name)));
    }
    out.push_str("];\n\n");
    out.push_str("/** Every operation of the registry, in registry order. */\n");
    out.push_str("export const OPERATIONS: readonly Operation[] = [\n");
    for op in ops {
        out.push_str(&entry(op));
    }
    out.push_str("];\n");
    out.push_str(TAIL);
    out
}
